	protected List<DataTask> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of DataTasks:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all DataTask : " );        
		List<DataTask> collection  = new ArrayList<>();

		try {
			// call the static get method on the DataTaskService
			collection = DataTaskService.getDataTaskInstance().getAllDataTask();
			assertNotNull( collection, "An Empty collection of DataTask was incorrectly returned.");
			
			// Now print out the values
			DataTask entity = null;            
			Iterator<DataTask> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getDataTaskId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

